onClick:
{{
  !selBalanceEmployee.selectedOptionValue ||
  !selBalanceLeaveType.selectedOptionValue ||
  !inpBalanceYear.text ||
  inpBalanceEntitled.text === "" ||
  inpBalanceCarryForward.text === "" ||
  Number(inpBalanceEntitled.text) < 0 ||
  Number(inpBalanceCarryForward.text) < 0
    ? showAlert("Please enter valid employee, leave type, year and balance values.", "warning")
    : q_hr_update_leave_balance.run()
        .then(data => {
          if (!data || data.length === 0) {
            showAlert("Update not applied. Check the balance values and existing used or pending days.", "warning");
            return;
          }

          showAlert("Leave balance updated successfully.", "success");

          return Promise.all([
            q_hr_get_balance_by_employee_t.run(),
            q_hr_get_leave_balances.run()
          ]);
        })
        .catch(error => {
          showAlert(error.message || "Unable to update leave balance.", "error");
        })
}}
